git rev-parse --abbrev-ref @{u}
# ¿Qué tiene el servidor que yo no? (behind)
git log --oneline ..@{u}
# ¿Qué tengo yo que el servidor no? (ahead)
git log --oneline @{u}..
# Los dos números de una vez: ahead y behind
git rev-list --left-right --count HEAD...@{u}
git for-each-ref --format="%(refname:short) %(upstream:short) %(upstream:track)" refs/heads

